  focus: LayerId | null;
  onHover: (h: Hover | null) => void;
  onSelect: (s: Selection, at: [number, number, number]) => void;
  /** page 2: comments fly into their clusters and the AI's structure appears on top */
  mode?: "scan" | "structure";
  structure?: StructurePayload;
