}
.sweepctl-top { display: grid; gap: 3px; }
.sweepctl-title { font-size: var(--t-label); font-weight: 600; color: var(--ink); }

/* the timeline: labels above the rail, ticks below it */
.sweepctl-line { position: relative; height: 40px; margin: 0 6px; }
.sweepctl-rail, .sweepctl-fill { position: absolute; left: 0; right: 0; top: 24px; height: 1px; }
.sweepctl-rail { background: var(--hair-2); }
